//! Verifies signatures made by an independent implementation, through both interfaces, and checks
//! every verdict against certval's software verifier.
//!
//! The elliptic curve signatures come from RustCrypto with fixed private scalars, so they are the
//! same on every run. RSA has no deterministic key generation in reach, so the RSA keys are
//! generated by OpenSSL itself; the software verifier is then what keeps those tests from being
//! circular, because it reads the same `SubjectPublicKeyInfo` and must agree.

use certval::{
    calculate_hash_rust_crypto, verify_signature_digest_rust_crypto,
    verify_signature_message_rust_crypto, CalculateHash, Error, PathValidationStatus,
    PkiEnvironment, VerifySignatureDigest, VerifySignatureMessage, PKIXALG_ECDSA_WITH_SHA224,
    PKIXALG_ECDSA_WITH_SHA256, PKIXALG_ECDSA_WITH_SHA384, PKIXALG_ECDSA_WITH_SHA512,
    PKIXALG_EC_PUBLIC_KEY, PKIXALG_MGF1, PKIXALG_RSASSA_PSS, PKIXALG_SECP256R1, PKIXALG_SECP384R1,
    PKIXALG_SECP521R1, PKIXALG_SHA1, PKIXALG_SHA224, PKIXALG_SHA256,
    PKIXALG_SHA256_WITH_RSA_ENCRYPTION, PKIXALG_SHA384, PKIXALG_SHA384_WITH_RSA_ENCRYPTION,
    PKIXALG_SHA512,
};
use certval_openssl::OpenSslCrypto;
use const_oid::ObjectIdentifier;
use der::asn1::{Any, BitString};
use der::Decode;
use openssl::hash::MessageDigest;
use openssl::pkey::{PKey, Private};
use openssl::rsa::{Padding, Rsa};
use openssl::sign::{RsaPssSaltlen, Signer};
use sha2::Digest;
use spki::{AlgorithmIdentifierOwned, SubjectPublicKeyInfoOwned};

const MESSAGE: &[u8] = b"a to-be-signed structure stands in here";

/// Set by the CI job that runs against OpenSSL's FIPS provider, so that a misconfigured runner
/// fails rather than quietly testing the default provider.
const EXPECT_FIPS: &str = "CERTVAL_OPENSSL_EXPECT_FIPS";

/// One signature together with what is needed to check it.
struct Case {
    spki: SubjectPublicKeyInfoOwned,
    alg: AlgorithmIdentifierOwned,
    signature: Vec<u8>,
    digest: Vec<u8>,
}

fn pe() -> PkiEnvironment {
    let mut pe = PkiEnvironment::default();
    pe.populate_5280_pki_environment();
    pe
}

fn bits(bytes: &[u8]) -> BitString {
    BitString::from_bytes(bytes).unwrap()
}

fn plain(oid: ObjectIdentifier) -> AlgorithmIdentifierOwned {
    AlgorithmIdentifierOwned {
        oid,
        parameters: None,
    }
}

fn ec_spki(curve: ObjectIdentifier, point: &[u8]) -> SubjectPublicKeyInfoOwned {
    SubjectPublicKeyInfoOwned {
        algorithm: AlgorithmIdentifierOwned {
            oid: PKIXALG_EC_PUBLIC_KEY,
            parameters: Some(Any::encode_from(&curve).unwrap()),
        },
        subject_public_key: bits(point),
    }
}

macro_rules! ec_case {
    ($curve:ident, $curve_oid:expr, $sig_oid:expr, $digest:ty, $scalar:expr) => {{
        use signature::hazmat::PrehashSigner;
        let key = $curve::ecdsa::SigningKey::from_slice(&$scalar).unwrap();
        let point = key.verifying_key().to_sec1_point(false);
        let digest = <$digest>::digest(MESSAGE).to_vec();
        let signature: $curve::ecdsa::Signature = key.sign_prehash(&digest).unwrap();
        Case {
            spki: ec_spki($curve_oid, point.as_bytes()),
            alg: plain($sig_oid),
            signature: signature.to_der().as_bytes().to_vec(),
            digest,
        }
    }};
}

fn ec_cases() -> Vec<(&'static str, Case)> {
    vec![
        (
            "P-256 SHA-224",
            ec_case!(
                p256,
                PKIXALG_SECP256R1,
                PKIXALG_ECDSA_WITH_SHA224,
                sha2::Sha224,
                [0x11u8; 32]
            ),
        ),
        (
            "P-256 SHA-256",
            ec_case!(
                p256,
                PKIXALG_SECP256R1,
                PKIXALG_ECDSA_WITH_SHA256,
                sha2::Sha256,
                [0x11u8; 32]
            ),
        ),
        (
            "P-384 SHA-384",
            ec_case!(
                p384,
                PKIXALG_SECP384R1,
                PKIXALG_ECDSA_WITH_SHA384,
                sha2::Sha384,
                [0x22u8; 48]
            ),
        ),
        (
            "P-521 SHA-512",
            ec_case!(
                p521,
                PKIXALG_SECP521R1,
                PKIXALG_ECDSA_WITH_SHA512,
                sha2::Sha512,
                {
                    // A P-521 scalar is 521 bits, so the top byte holds a single bit.
                    let mut s = [0x33u8; 66];
                    s[0] = 0x01;
                    s
                }
            ),
        ),
    ]
}

fn rsa_key(bits: u32) -> PKey<Private> {
    PKey::from_rsa(Rsa::generate(bits).unwrap()).unwrap()
}

/// The key's `SubjectPublicKeyInfo` as OpenSSL encodes it, which is under `rsaEncryption`.
fn rsa_spki(key: &PKey<Private>) -> SubjectPublicKeyInfoOwned {
    SubjectPublicKeyInfoOwned::from_der(&key.public_key_to_der().unwrap()).unwrap()
}

/// The same key re-identified as `id-RSASSA-PSS` with no parameters, which leaves it unrestricted
/// within PSS.
fn rsa_pss_spki(key: &PKey<Private>) -> SubjectPublicKeyInfoOwned {
    let mut spki = rsa_spki(key);
    spki.algorithm = plain(PKIXALG_RSASSA_PSS);
    spki
}

fn pss_alg(
    hash: ObjectIdentifier,
    mgf_hash: ObjectIdentifier,
    salt_len: u32,
) -> AlgorithmIdentifierOwned {
    #[derive(der::Sequence)]
    struct Params {
        #[asn1(context_specific = "0", tag_mode = "EXPLICIT")]
        hash: AlgorithmIdentifierOwned,
        #[asn1(context_specific = "1", tag_mode = "EXPLICIT")]
        mask_gen: AlgorithmIdentifierOwned,
        #[asn1(context_specific = "2", tag_mode = "EXPLICIT")]
        salt_len: u32,
    }
    let alg = |oid| AlgorithmIdentifierOwned {
        oid,
        parameters: Some(Any::null()),
    };
    let params = Params {
        hash: alg(hash),
        mask_gen: AlgorithmIdentifierOwned {
            oid: PKIXALG_MGF1,
            parameters: Some(Any::encode_from(&alg(mgf_hash)).unwrap()),
        },
        salt_len,
    };
    AlgorithmIdentifierOwned {
        oid: PKIXALG_RSASSA_PSS,
        parameters: Some(Any::encode_from(&params).unwrap()),
    }
}

fn sign_pkcs1(key: &PKey<Private>, md: MessageDigest) -> Vec<u8> {
    let mut signer = Signer::new(md, key).unwrap();
    signer.set_rsa_padding(Padding::PKCS1).unwrap();
    signer.sign_oneshot_to_vec(MESSAGE).unwrap()
}

fn sign_pss(key: &PKey<Private>, md: MessageDigest, mgf: MessageDigest, salt_len: i32) -> Vec<u8> {
    let mut signer = Signer::new(md, key).unwrap();
    signer.set_rsa_padding(Padding::PKCS1_PSS).unwrap();
    signer.set_rsa_mgf1_md(mgf).unwrap();
    signer
        .set_rsa_pss_saltlen(RsaPssSaltlen::custom(salt_len))
        .unwrap();
    signer.sign_oneshot_to_vec(MESSAGE).unwrap()
}

fn rsa_cases() -> Vec<(&'static str, Case)> {
    let key = rsa_key(2048);
    let key3072 = rsa_key(3072);
    let sha256 = sha2::Sha256::digest(MESSAGE).to_vec();
    let sha384 = sha2::Sha384::digest(MESSAGE).to_vec();
    vec![
        (
            "RSA-2048 PKCS #1 SHA-256",
            Case {
                spki: rsa_spki(&key),
                alg: plain(PKIXALG_SHA256_WITH_RSA_ENCRYPTION),
                signature: sign_pkcs1(&key, MessageDigest::sha256()),
                digest: sha256.clone(),
            },
        ),
        (
            "RSA-3072 PKCS #1 SHA-384",
            Case {
                spki: rsa_spki(&key3072),
                alg: plain(PKIXALG_SHA384_WITH_RSA_ENCRYPTION),
                signature: sign_pkcs1(&key3072, MessageDigest::sha384()),
                digest: sha384.clone(),
            },
        ),
        (
            "RSA-2048 PSS SHA-256, 32-byte salt",
            Case {
                spki: rsa_spki(&key),
                alg: pss_alg(PKIXALG_SHA256, PKIXALG_SHA256, 32),
                signature: sign_pss(&key, MessageDigest::sha256(), MessageDigest::sha256(), 32),
                digest: sha256.clone(),
            },
        ),
        (
            "RSA-2048 PSS SHA-256, 20-byte salt",
            Case {
                spki: rsa_spki(&key),
                alg: pss_alg(PKIXALG_SHA256, PKIXALG_SHA256, 20),
                signature: sign_pss(&key, MessageDigest::sha256(), MessageDigest::sha256(), 20),
                digest: sha256,
            },
        ),
        (
            "RSA-3072 PSS SHA-384 under an id-RSASSA-PSS key",
            Case {
                spki: rsa_pss_spki(&key3072),
                alg: pss_alg(PKIXALG_SHA384, PKIXALG_SHA384, 48),
                signature: sign_pss(
                    &key3072,
                    MessageDigest::sha384(),
                    MessageDigest::sha384(),
                    48,
                ),
                digest: sha384,
            },
        ),
    ]
}

fn all_cases() -> Vec<(&'static str, Case)> {
    let mut cases = ec_cases();
    cases.extend(rsa_cases());
    cases
}

fn is_rejection(result: &certval::Result<()>) -> bool {
    matches!(
        result,
        Err(Error::PathValidation(
            PathValidationStatus::SignatureVerificationFailure
        ))
    )
}

#[test]
fn fips_mode_is_reported() {
    let enabled = OpenSslCrypto::fips_mode_enabled();
    println!(
        "{}; FIPS default properties: {enabled}",
        OpenSslCrypto::openssl_version()
    );
    if std::env::var_os(EXPECT_FIPS).is_some() {
        assert!(
            enabled,
            "{EXPECT_FIPS} is set but OpenSSL is not requiring fips=yes"
        );
    }
}

#[test]
fn hashes_match_software() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    for oid in [
        PKIXALG_SHA1,
        PKIXALG_SHA224,
        PKIXALG_SHA256,
        PKIXALG_SHA384,
        PKIXALG_SHA512,
    ] {
        let got = crypto.calculate_hash(&pe, &plain(oid), MESSAGE).unwrap();
        // certval's software hash has no SHA-1, so there is nothing to compare that one against
        // beyond its length.
        match calculate_hash_rust_crypto(&pe, &plain(oid), MESSAGE) {
            Ok(expected) => assert_eq!(got, expected, "{oid}"),
            Err(_) => assert_eq!(got.len(), 20, "{oid}"),
        }
    }
}

#[test]
fn good_signatures_verify_through_both_interfaces() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    for (name, case) in all_cases() {
        let signature = bits(&case.signature);

        let platform =
            crypto.verify_signature_message(&pe, MESSAGE, &signature, &case.alg, &case.spki);
        assert!(platform.is_ok(), "{name}, message: {platform:?}");
        // certval's software verifier has no ECDSA with SHA-224, and declining is not
        // disagreeing, so only a software verdict is compared.
        let software =
            verify_signature_message_rust_crypto(&pe, MESSAGE, &signature, &case.alg, &case.spki);
        assert!(
            matches!(software, Ok(()) | Err(Error::Unrecognized)),
            "{name}, software disagrees on the message: {software:?}"
        );

        let platform =
            crypto.verify_signature_digest(&pe, &case.digest, &signature, &case.alg, &case.spki);
        assert!(platform.is_ok(), "{name}, digest: {platform:?}");
    }
}

#[test]
fn a_changed_message_is_a_verdict_not_a_refusal() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    let other = b"a different to-be-signed structure";
    for (name, case) in all_cases() {
        let signature = bits(&case.signature);
        let platform =
            crypto.verify_signature_message(&pe, other, &signature, &case.alg, &case.spki);
        assert!(is_rejection(&platform), "{name}: {platform:?}");
        let software =
            verify_signature_message_rust_crypto(&pe, other, &signature, &case.alg, &case.spki);
        assert!(
            software.is_err(),
            "{name}: software accepted a changed message"
        );
    }
}

#[test]
fn a_changed_signature_is_a_verdict_not_a_refusal() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    for (name, case) in all_cases() {
        let mut tampered = case.signature.clone();
        // The last byte is inside the signature value for every encoding here: the low byte of `s`
        // for a DER ECDSA signature, and the low byte of the integer for RSA.
        *tampered.last_mut().unwrap() ^= 0x01;
        let signature = bits(&tampered);

        let platform =
            crypto.verify_signature_message(&pe, MESSAGE, &signature, &case.alg, &case.spki);
        assert!(is_rejection(&platform), "{name}, message: {platform:?}");

        let platform =
            crypto.verify_signature_digest(&pe, &case.digest, &signature, &case.alg, &case.spki);
        assert!(is_rejection(&platform), "{name}, digest: {platform:?}");
    }
}

#[test]
fn a_pss_signature_with_the_wrong_salt_length_is_a_verdict() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    let key = rsa_key(2048);
    let signature = sign_pss(&key, MessageDigest::sha256(), MessageDigest::sha256(), 32);
    // The signature was made with a 32-byte salt, so a parameter block naming 20 describes a
    // different signature, and OpenSSL, told 20, must find it invalid.
    let alg = pss_alg(PKIXALG_SHA256, PKIXALG_SHA256, 20);
    let result =
        crypto.verify_signature_message(&pe, MESSAGE, &bits(&signature), &alg, &rsa_spki(&key));
    assert!(is_rejection(&result), "{result:?}");
}

#[test]
fn a_pss_mask_over_another_hash_is_verified() {
    // OpenSSL takes the MGF1 hash separately, so it verifies a combination certval's software
    // verifier declines. This is capability the provider adds, not a disagreement.
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    let key = rsa_key(2048);
    let signature = sign_pss(&key, MessageDigest::sha256(), MessageDigest::sha512(), 32);
    let alg = pss_alg(PKIXALG_SHA256, PKIXALG_SHA512, 32);
    let spki = rsa_spki(&key);
    let result = crypto.verify_signature_message(&pe, MESSAGE, &bits(&signature), &alg, &spki);
    assert!(result.is_ok(), "{result:?}");
    let software =
        verify_signature_message_rust_crypto(&pe, MESSAGE, &bits(&signature), &alg, &spki);
    assert!(matches!(software, Err(Error::Unrecognized)), "{software:?}");
}

#[test]
fn a_pkcs1_signature_under_a_pss_key_is_left_to_software() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    let key = rsa_key(2048);
    let spki = rsa_pss_spki(&key);
    let signature = sign_pkcs1(&key, MessageDigest::sha256());
    let alg = plain(PKIXALG_SHA256_WITH_RSA_ENCRYPTION);

    let result = crypto.verify_signature_message(&pe, MESSAGE, &bits(&signature), &alg, &spki);
    assert!(matches!(result, Err(Error::Unrecognized)), "{result:?}");

    let software =
        verify_signature_message_rust_crypto(&pe, MESSAGE, &bits(&signature), &alg, &spki);
    assert!(is_rejection(&software), "{software:?}");
}

#[test]
fn a_digest_of_the_wrong_length_is_declined() {
    let pe = pe();
    let crypto = OpenSslCrypto::new();
    for (name, case) in all_cases() {
        let short = &case.digest[..case.digest.len() - 1];
        let result = crypto.verify_signature_digest(
            &pe,
            short,
            &bits(&case.signature),
            &case.alg,
            &case.spki,
        );
        assert!(
            matches!(result, Err(Error::Unrecognized)),
            "{name}: {result:?}"
        );
    }
}

#[test]
fn registered_first_it_answers_and_software_agrees() {
    let mut pe = PkiEnvironment::default();
    pe.add_calculate_hash_callback(OpenSslCrypto::new());
    pe.add_verify_signature_message_callback(OpenSslCrypto::new());
    pe.add_verify_signature_digest_callback(OpenSslCrypto::new());
    pe.populate_5280_pki_environment();

    for (name, case) in all_cases() {
        let signature = bits(&case.signature);
        assert!(
            pe.verify_signature_message(&pe, MESSAGE, &signature, &case.alg, &case.spki)
                .is_ok(),
            "{name}"
        );
        // certval's software digest verifier covers RSA only, so only where it has an opinion is
        // there a software verdict to agree with.
        if verify_signature_digest_rust_crypto(&pe, &case.digest, &signature, &case.alg, &case.spki)
            .is_ok()
        {
            assert!(
                pe.verify_signature_digest(&pe, &case.digest, &signature, &case.alg, &case.spki)
                    .is_ok(),
                "{name}"
            );
        }
    }
}
